 ``

 `_fetchModelsHttp`:
 ```dart
 Future<ModelsFetchReport> _fetchModelsHttp(String base, Map<String,String> headers, http.Client client, {String? tierHint}) async {
   http.Response response;
   try {
     response = await client.get(Uri.parse('$base/models'), headers: headers).timeout(15s);
