Future<ModelsFetchReport> _fetchWithFallback(String baseUrl, String apiKey, http.Client client) async {
 final configuredBase = baseUrl.replaceAll(_trailingSlashes, '');
 final patDirectFirst = isFineGrainedGitHubPat(apiKey);

 Future<ModelsFetchReport> runPath({required bool patDirect}) => patDirect
     ? _fetchModelsDirectPat(configuredBase, apiKey, client)
     : _fetchModelsViaExchange(configuredBase, apiKey, client);

 final primary = await runPath(patDirect: patDirectFirst);
 final primaryFailed = primary.diagnostic != null && primary.diagnostic!.pathFailed;
 if (!primaryFailed) return primary;

 // Dual-path fallback (gh-1990): the primary credential path is dead —
 // give the other path ONE attempt before declaring empty. A fine-grained
 // PAT never retries into the exchange (GitHub 404s every PAT exchange by
 // design — copilot_oauth.dart); an OAuth token (gho_/ghu_/ghs_) never
 // retries into PAT-direct (the exchange is its only credential shape).
 final canFallback = patDirectFirst ? false : !_isOAuthShapedGitHubKey(apiKey);
 if (!canFallback) return primary;

 final secondary = await runPath(patDirect: true);
 final secondaryFailed = secondary.diagnostic != null && secondary.diagnostic!.pathFailed;
 if (!secondaryFailed) {
   // The fallback path answered — note the provenance (AC3).
   final reason = primary.diagnostic!.message;
   return _withNote(secondary, 'models via the pat-direct fallback '
       '(the exchange path failed: $reason)');
 }
 // Both paths failed — one combined reason (AC3).
 final a = primary.diagnostic!, b = secondary.diagnostic!;
 return ModelsFetchReport(
   info: secondary.info, // empty
   diagnostic: ModelsFetchDiagnostic(
     stage: '${a.stage}+${b.stage}',
     path: a.path,
     httpStatus: a.httpStatus ?? b.httpStatus,
     timedOut: a.timedOut || b.timedOut,
     message: '${a.path} path: ${a.message}; ${b.path} path: ${b.message}',
     hint: a.hint ?? b.hint,
   ),
 );
}
``

