/// Why a `/models` fetch answered empty — the named failure branch
/// (gh-1990): no model picker may show a bare empty list again; every
/// silent-empty exit (token exchange, HTTP, filter) carries its reason.
final class ModelsFetchDiagnostic {
 const ModelsFetchDiagnostic({
   required this.stage,
   required this.message,
   this.path,
   this.httpStatus,
   this.timedOut = false,
   this.pathFailed = true,
   this.fetchedCount = 0,
   this.filteredCount = 0,
   this.hint,
 });

 /// The failed stage: token exchange, the /models HTTP call, or the
 /// picker filter.
 final String stage;
 static const stageExchange = 'exchange';
 static const stageModels = 'models';
 static const stageFilter = 'filter';

 /// Which credential path produced this: the exchanged-token path or the
 /// raw-PAT path (dual-path fallback provenance, gh-1606).
 final String? path;
 static const pathExchange = 'exchange';
 static const pathPatDirect = 'pat-direct';

 /// The one-line user-facing reason.
 final String message;

 /// HTTP status when a request failed with one.
 final int? httpStatus;
 final bool timedOut;

 /// Whether THIS path failed (vs answered with a filtered-down list) —
 /// the dual-path fallback retries only failed paths.
 final bool pathFailed;

 /// Entries the payload carried / the filter dropped.
 final int fetchedCount;
 final int filteredCount;

 /// Optional remediation (tier host, PAT remedies, seat check).
 final String? hint;
}
